const results = $input.first().json.local_results || [];

const userInput = $('On form submission').first().json;

const structuredData = results.slice(0, 5).map(place => ({
  business_name: place.title || null,
  category: place.type || null,
  address: place.address || null,
  rating: place.rating || null,
  reviews_count: place.reviews || 0,
  reviews_link: place.reviews_link || null,
  phone: place.phone || null,
  website: place.website || null,

  coordinates: {
    latitude: place.gps_coordinates?.latitude || null,
    longitude: place.gps_coordinates?.longitude || null
  },

  opening_hours: place.operating_hours || null,
  price_level: place.price_level || null,

  search_context: {
    search_query: userInput.search_query,
    location: userInput.Location,
    language: userInput.Langauge,
    business_category: userInput['business category'],
    city_name: userInput.city_name
  }
}));

return structuredData.map(item => ({
  json: item
}));

const business = $('Loop Over Items').item.json;
const reviewResponse = $input.first().json;

const reviews = reviewResponse.reviews || [];

const cleanReviews = reviews.map(review => ({
  author: review.user?.name || null,
  rating: review.rating || null,
  text: review.snippet || review.text || null,
  date: review.date || null
}));

return [
  {
    json: {
      business_name: business.business_name,
      category: business.category,
      address: business.address,
      rating: business.rating,
      reviews_count: business.reviews_count,
      phone: business.phone,
      website: business.website,

      coordinates: business.coordinates,
      opening_hours: business.opening_hours,
      price_level: business.price_level,

      reviews: cleanReviews,

      review_summary: {
        total_reviews_fetched: cleanReviews.length,
        average_rating:
          cleanReviews.length > 0
            ? (
                cleanReviews.reduce(
                  (sum, review) => sum + (Number(review.rating) || 0),
                  0
                ) / cleanReviews.length
              ).toFixed(2)
            : null
      },

      search_context: business.search_context
    }
  }
];

const data = $input.first().json;

// Find the aggregated business data
const businesses =
  data.data ||
  data.items ||
  data.records ||
  [];

const organizedBusinesses = businesses.map((business, index) => {
  const reviews = business.reviews || [];

  return {
    business_id: index + 1,

    business: {
      name: business.business_name || null,
      category: business.category || null,
      address: business.address || null,
      phone: business.phone || null,
      website: business.website || null
    },

    performance: {
      rating: business.rating || null,
      total_reviews: business.reviews_count || 0,
      fetched_reviews: reviews.length
    },

    pricing: {
      price_level: business.price_level || null
    },

    location: {
      latitude: business.coordinates?.latitude || null,
      longitude: business.coordinates?.longitude || null
    },

    opening_hours: business.opening_hours || null,

    customer_reviews: reviews.map(review => ({
      author: review.author || null,
      rating: review.rating || null,
      text: review.text || null,
      date: review.date || null
    })),

    review_summary: business.review_summary || {
      total_reviews_fetched: reviews.length,
      average_rating: null
    }
  };
});

return [
  {
    json: {
      research: {
  query: $('Edit Fields').first().json['Search Query'],
  location: $('Edit Fields').first().json['Location'],
  country_code: $('Edit Fields').first().json['Country Code'],
  language: $('On form submission').first().json['Language'],
  business_category: $('Edit Fields').first().json['Business Category'],
  city: $('Edit Fields').first().json['City Name']
},

      dataset_summary: {
        total_businesses: organizedBusinesses.length
      },

      businesses: organizedBusinesses
    }
  }
];
